def ev(id, sid, locator, quote, meaning, pages=None, verification='本地正文核对；官方发布来源回查'):
    return dict(id=id, source_id=sid, locator=locator, physical_pdf_pages=pages or [], quote_fragment=quote,
                supported_content=meaning, verification=verification)

