def norm(s):
    return re.sub(r'\s+', '', s).replace('；',';').replace('，',',').replace('（','(').replace('）',')')

src_map={s['id']:s for s in SOURCES}
for r in ROWS:
    if r['group']=='药监' and r['dimension']=='经济性':
        for e in r['evidence']:
            e['analysis_unit_id']={'NMPA-Ec1':'RECODE25-04088','NMPA-Ec2':'RECODE25-03016'}[e['id']]
checks=[]
for r in ROWS:
    for e in r['evidence']:
        p=Path(src_map[e['source_id']]['local_path'])
        if p.suffix=='.pdf':
            doc=fitz.open(p)
            text=''.join(doc[i-1].get_text() for i in (e['physical_pdf_pages'] or range(1,len(doc)+1)))
        else:text=p.read_text()
        if e['source_id']=='CARE':status='scanned_source_visually_verified'
        else:status='matched' if norm(e['quote_fragment']) in norm(text) else 'needs_review'
        checks.append(dict(evidence_id=e['id'],quote_check=status))

